if (typeof THREE === 'undefined') return;

if (!gdjs.__advancedMaterials) {
    gdjs.__advancedMaterials = (function() {
        const copiedProps = [
            'map', 'alphaMap', 'aoMap', 'lightMap', 'normalMap', 'bumpMap', 'displacementMap',
            'roughnessMap', 'metalnessMap', 'emissiveMap', 'envMap', 'color', 'opacity',
            'transparent', 'alphaTest', 'side', 'name', 'vertexColors', 'blending',
            'depthWrite', 'depthTest', 'visible', 'wireframe', 'emissive',
            'emissiveIntensity', 'roughness', 'metalness', 'ior', 'transmission',
            'thickness', 'clearcoat', 'clearcoatRoughness', 'attenuationColor',
            'attenuationDistance', 'sheen', 'sheenColor', 'sheenRoughness'
        ];

        let nextBehaviorId = 1;

        const getRootObject3D = (object) => {
            if (!object) return null;
            if (typeof object.get3DRendererObject === 'function') {
                try {
                    const obj = object.get3DRendererObject();
                    if (obj) return obj;
                } catch(e) {}
            }
            return null;
        };

        const makeReplacementStore = () => {
            if (typeof WeakMap !== 'undefined') {
                const map = new WeakMap();
                return {
                    get: (key) => map.get(key),
                    set: (key, value) => map.set(key, value)
                };
            }
            const entries = [];
            return {
                get: (key) => {
                    const found = entries.find((entry) => entry.key === key);
                    return found ? found.value : undefined;
                },
                set: (key, value) => entries.push({ key, value })
            };
        };

        const getBehaviorState = (behavior) => {
            if (!behavior.__advancedMaterialsState) {
                behavior.__advancedMaterialsState = {
                    ownerId: nextBehaviorId++,
                    initialized: false,
                    replacements: makeReplacementStore(),
                    ownedMaterials: [],
                    activeMaterials: [],
                    originalAssignments: [],
                    materialCount: 0,
                    lastError: '',
                    lastSignature: '',
                    rootObject: null
                };
            }
            return behavior.__advancedMaterialsState;
        };

        const resetState = (state) => {
            state.initialized = false;
            state.replacements = makeReplacementStore();
            state.ownedMaterials = [];
            state.activeMaterials = [];
            state.originalAssignments = [];
            state.materialCount = 0;
            state.lastSignature = '';
            state.rootObject = null;
        };

        const getNumber = (behavior, name, def) => {
            const g = behavior['_get' + name];
            if (typeof g !== 'function') return def;
            const v = Number(g.call(behavior));
            return Number.isFinite(v) ? v : def;
        };

        const getBoolean = (behavior, name, def) => {
            const g = behavior['_get' + name];
            if (typeof g !== 'function') return def;
            const v = g.call(behavior);
            return v === true || v === 'true' || v === 1 || v === '1';
        };

        const getString = (behavior, name, def) => {
            const g = behavior['_get' + name];
            return typeof g === 'function' ? String(g.call(behavior)) : def;
        };

        const parseColor = (colorString, fallback) => {
            const color = new THREE.Color();
            if (!colorString) return color.copy(fallback || new THREE.Color(1, 1, 1));
            if (colorString.indexOf(';') === -1) {
                try {
                    color.set(colorString);
                    return color;
                } catch(e) {
                    return color.copy(fallback || new THREE.Color(1, 1, 1));
                }
            }
            const parts = colorString.split(';');
            const r = Math.max(0, Math.min(255, Number(parts[0]) || 0)) / 255;
            const g = Math.max(0, Math.min(255, Number(parts[1]) || 0)) / 255;
            const b = Math.max(0, Math.min(255, Number(parts[2]) || 0)) / 255;
            color.setRGB(r, g, b, THREE.SRGBColorSpace);
            return color;
        };

        const rememberOriginals = (material, source) => {
            if (!material.userData) material.userData = {};
            if (!material.userData.__advancedMaterialsOriginals) {
                material.userData.__advancedMaterialsOriginals = {
                    color: source.color && source.color.clone ? source.color.clone() : new THREE.Color(1, 1, 1),
                    emissive: source.emissive && source.emissive.clone ? source.emissive.clone() : new THREE.Color(0, 0, 0),
                    emissiveIntensity: source.emissiveIntensity !== undefined ? source.emissiveIntensity : 0,
                    opacity: source.opacity !== undefined ? source.opacity : 1,
                    transparent: !!source.transparent,
                    alphaTest: source.alphaTest !== undefined ? source.alphaTest : 0,
                    side: source.side !== undefined ? source.side : THREE.FrontSide
                };
            }
        };

        const copyValue = (value) => {
            if (value && value.isColor && value.clone) return value.clone();
            return value;
        };

        const addOwnedMaterial = (state, material) => {
            if (material && state.ownedMaterials.indexOf(material) === -1) {
                state.ownedMaterials.push(material);
            }
        };

        const makePhysicalMaterial = (state, source) => {
            const material = new THREE.MeshPhysicalMaterial();
            for (const prop of copiedProps) {
                if (source[prop] !== undefined && material[prop] !== undefined) {
                    material[prop] = copyValue(source[prop]);
                }
            }
            material.userData = Object.assign({}, source.userData || {});
            material.__advancedMaterialsManaged = true;
            material.__advancedMaterialsOwnerId = state.ownerId;
            rememberOriginals(material, source);
            material.needsUpdate = true;
            addOwnedMaterial(state, material);
            return material;
        };

        const getManagedMaterial = (state, source) => {
            if (!source) return source;
            if (source.__advancedMaterialsManaged && source.__advancedMaterialsOwnerId === state.ownerId) {
                addOwnedMaterial(state, source);
                return source;
            }
            const existing = state.replacements.get(source);
            if (existing) return existing;
            const material = makePhysicalMaterial(state, source);
            state.replacements.set(source, material);
            return material;
        };

        const rememberOriginalAssignment = (state, mesh) => {
            for (const assignment of state.originalAssignments) {
                if (assignment.mesh === mesh) return;
            }
            const wasArray = Array.isArray(mesh.material);
            state.originalAssignments.push({
                mesh,
                wasArray,
                material: wasArray ? mesh.material.slice() : mesh.material
            });
        };

        const syncMeshMaterials = (state, root) => {
            const activeMaterials = [];
            const visit = (child) => {
                if (!child.isMesh || !child.material) return;
                const wasArray = Array.isArray(child.material);
                const oldMats = wasArray ? child.material : [child.material];
                const newMats = oldMats.map((mat) => getManagedMaterial(state, mat));
                const changed = newMats.some((mat, index) => mat !== oldMats[index]);
                if (changed) {
                    rememberOriginalAssignment(state, child);
                    child.material = wasArray ? newMats : newMats[0];
                }
                for (const mat of newMats) {
                    if (mat && activeMaterials.indexOf(mat) === -1) activeMaterials.push(mat);
                }
            };
            if (root.traverse) root.traverse(visit);
            else visit(root);
            state.activeMaterials = activeMaterials;
            state.materialCount = activeMaterials.length;
            return activeMaterials;
        };

        const applyToMaterial = (mat, settings) => {
            const originals = mat.userData && mat.userData.__advancedMaterialsOriginals;

            if (settings.useBaseColor && mat.color) {
                mat.color.copy(parseColor(settings.baseColor, originals && originals.color));
            } else if (originals && originals.color && mat.color) {
                mat.color.copy(originals.color);
            }

            mat.metalness = Math.max(0, Math.min(1, settings.metallic));
            mat.roughness = Math.max(0, Math.min(1, settings.roughness));

            if (mat.ior !== undefined) mat.ior = Math.max(1, Math.min(2.333, settings.ior));
            if (mat.clearcoat !== undefined) mat.clearcoat = Math.max(0, Math.min(1, settings.clearcoat));
            if (mat.clearcoatRoughness !== undefined) mat.clearcoatRoughness = Math.max(0, Math.min(1, settings.clearcoatRoughness));
            if (mat.transmission !== undefined) mat.transmission = Math.max(0, Math.min(1, settings.transmission));
            if (mat.thickness !== undefined) mat.thickness = Math.max(0, settings.thickness);

            if (settings.useEmission && mat.emissive) {
                mat.emissive.copy(parseColor(settings.emissionColor, originals && originals.emissive));
                mat.emissiveIntensity = Math.max(0, settings.emissionStrength);
            } else if (originals && mat.emissive) {
                mat.emissive.copy(originals.emissive);
                mat.emissiveIntensity = originals.emissiveIntensity;
            }

            if (settings.alphaMode === 'Opaque') {
                mat.transparent = false;
                mat.opacity = 1;
                mat.alphaTest = 0;
            } else if (settings.alphaMode === 'Blend') {
                mat.transparent = true;
                mat.opacity = Math.max(0, Math.min(1, settings.alpha));
                mat.alphaTest = 0;
            } else if (settings.alphaMode === 'Cutout') {
                mat.transparent = false;
                mat.opacity = 1;
                mat.alphaTest = Math.max(0, Math.min(1, settings.alpha));
            } else if (originals) {
                mat.transparent = originals.transparent;
                mat.opacity = originals.opacity;
                mat.alphaTest = originals.alphaTest;
            }

            if (settings.sideMode === 'Front') mat.side = THREE.FrontSide;
            else if (settings.sideMode === 'Back') mat.side = THREE.BackSide;
            else if (settings.sideMode === 'Double') mat.side = THREE.DoubleSide;
            else if (originals) mat.side = originals.side;

            mat.needsUpdate = true;
        };

        const readSettings = (behavior) => ({
            useBaseColor: getBoolean(behavior, 'UseBaseColor', false),
            baseColor: getString(behavior, 'BaseColor', '255;255;255'),
            metallic: getNumber(behavior, 'Metallic', 0),
            roughness: getNumber(behavior, 'Roughness', 0.5),
            ior: getNumber(behavior, 'IOR', 1.5),
            clearcoat: getNumber(behavior, 'Clearcoat', 0),
            clearcoatRoughness: getNumber(behavior, 'ClearcoatRoughness', 0),
            transmission: getNumber(behavior, 'Transmission', 0),
            thickness: getNumber(behavior, 'Thickness', 0),
            useEmission: getBoolean(behavior, 'UseEmission', false),
            emissionColor: getString(behavior, 'EmissionColor', '0;0;0'),
            emissionStrength: getNumber(behavior, 'EmissionStrength', 1),
            alphaMode: getString(behavior, 'AlphaMode', 'Preserve'),
            alpha: getNumber(behavior, 'Alpha', 1),
            sideMode: getString(behavior, 'Side', 'Preserve')
        });

        const settingsSignature = (settings) => [
            settings.useBaseColor,
            settings.baseColor,
            settings.metallic,
            settings.roughness,
            settings.ior,
            settings.clearcoat,
            settings.clearcoatRoughness,
            settings.transmission,
            settings.thickness,
            settings.useEmission,
            settings.emissionColor,
            settings.emissionStrength,
            settings.alphaMode,
            settings.alpha,
            settings.sideMode
        ].join('|');

        const applyToBehavior = (behavior, object, force) => {
            const state = getBehaviorState(behavior);
            const settings = readSettings(behavior);
            const signature = settingsSignature(settings);
            const root = getRootObject3D(object);
            if (!root) {
                state.lastError = 'The object renderer is not ready or is not a compatible 3D object.';
                return false;
            }
            if (force === false && state.initialized && state.rootObject === root && state.lastSignature === signature) {
                state.lastError = '';
                return true;
            }

            const materials = syncMeshMaterials(state, root);
            if (materials.length === 0) {
                state.lastError = 'No compatible 3D mesh materials were found on the object.';
                return false;
            }

            for (const mat of materials) applyToMaterial(mat, settings);
            state.initialized = true;
            state.rootObject = root;
            state.lastSignature = signature;
            state.lastError = '';
            return true;
        };

        const restoreMaterialValues = (mat) => {
            const originals = mat.userData && mat.userData.__advancedMaterialsOriginals;
            if (!originals) return;
            if (mat.color && originals.color) mat.color.copy(originals.color);
            if (mat.emissive && originals.emissive) mat.emissive.copy(originals.emissive);
            if (mat.emissiveIntensity !== undefined) mat.emissiveIntensity = originals.emissiveIntensity;
            mat.opacity = originals.opacity;
            mat.transparent = originals.transparent;
            mat.alphaTest = originals.alphaTest;
            mat.side = originals.side;
            mat.needsUpdate = true;
        };

        const restoreAssignments = (state) => {
            for (const mat of state.activeMaterials) restoreMaterialValues(mat);
            for (const assignment of state.originalAssignments) {
                if (!assignment.mesh) continue;
                assignment.mesh.material = assignment.wasArray ? assignment.material.slice() : assignment.material;
            }
        };

        const disposeOwnedMaterials = (state) => {
            for (const mat of state.ownedMaterials) {
                if (mat && typeof mat.dispose === 'function') mat.dispose();
            }
        };

        const restoreBehavior = (behavior, object) => {
            const state = getBehaviorState(behavior);
            if (state.activeMaterials.length === 0 && state.originalAssignments.length === 0) {
                const root = getRootObject3D(object);
                if (root) syncMeshMaterials(state, root);
            }
            if (state.activeMaterials.length === 0 && state.originalAssignments.length === 0) {
                state.lastError = 'No managed Advanced Materials values were found to restore.';
                return false;
            }
            restoreAssignments(state);
            disposeOwnedMaterials(state);
            resetState(state);
            state.lastError = '';
            return true;
        };

        const disposeBehavior = (behavior) => {
            const state = getBehaviorState(behavior);
            if (state.activeMaterials.length > 0 || state.originalAssignments.length > 0) {
                restoreAssignments(state);
            }
            disposeOwnedMaterials(state);
            resetState(state);
            state.lastError = '';
        };

        return { getBehaviorState, applyToBehavior, restoreBehavior, disposeBehavior };
    })();
    gdjs.__blenderMaterial = gdjs.__advancedMaterials;
}

gdjs.__advancedMaterials.applyToBehavior(behavior, object, false);
